% From a shell: matlab -batch "openProject('C:/work/myproj'); runtests('tests')"
proj = openProject("C:/work/myproj");
results = runtests(proj.RootFolder + "/tests");

export(currentProject, "release/myproj.mlproj");   % on the source machine
root = matlab.project.extractProject("myproj.mlproj", "C:/work");
openProject(root);

proj = currentProject;
updateDependencies(proj);
res = runChecks(proj);
tbl = table(res);
tbl(~[res.Passed], :)

function plan = buildfile
import matlab.buildtool.tasks.*
plan = buildplan(localfunctions);
plan("check") = CodeIssuesTask;
plan("test") = TestTask("tests", SourceFiles="src");
plan("archive").Dependencies = ["check" "test"];
plan.DefaultTasks = "archive";
end

function archiveTask(~)
% Create ZIP file of the toolbox
zip("release.zip", "src");
end

cfg = coder.config("lib");
cfg.TargetLang = "C++";
cfg.GenerateReport = true;
codegen -config cfg myFilter -args {zeros(1,1024)} -report

results = compiler.build.standaloneApplication("magicsquare.m", ...
    ExecutableName="magic", OutputDir="build", TreatInputsAsNumeric=true);
% run:  build\magic.exe 4

results = compiler.build.standaloneApplication("magicsquare.m");
compiler.package.installer(results, InstallerName="MagicSetup", ...
    RuntimeDelivery="installer", ApplicationName="Magic Square", Version="1.1");

res = compiler.build.standaloneApplication("magicsquare.m");
compiler.package.docker(res, ImageName="magicapp");
% shell:  docker run --rm -e "DISPLAY=:0" magicapp 5

if isdeployed
    dataDir = fullfile(ctfroot, "data");
else
    dataDir = fullfile(fileparts(mfilename("fullpath")), "data");
    addpath("helpers")   % addpath is not allowed in deployed code
end
